arguments.rscript:
# Load required libraries
library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(readr)

# Load all necessary files
wave4 <- read_delim('data/input/wave_four_lsype_young_person_2020.tab', delim = '\t')
wave6 <- read_delim('data/input/wave_six_lsype_young_person_2020.tab', delim = '\t')
wave7 <- read_delim('data/input/wave_seven_lsype_young_person_2020.tab', delim = '\t')
wave8 <- read_delim('data/input/ns8_2015_main_interview.tab', delim = '\t')
wave9 <- read_delim('data/input/ns9_2022_main_interview.tab', delim = '\t')

# Merge datasets by NSID
merged_data <- full_join(wave4, wave6, by = 'NSID')
merged_data <- full_join(merged_data, wave7, by = 'NSID')
merged_data <- full_join(merged_data, wave8, by = 'NSID')
merged_data <- full_join(merged_data, wave9, by = 'NSID')

# Function to map young person education aims
map_young_education <- function(var, wave_age) {
  if (wave_age == 17) {
    if (var %in% c(1, 2, 3, 4, 5, 6, 7)) return(1)
    if (var == 8) return(2)
    if (var %in% c(9, 10, 11)) return(2)
    if (var == 12 || var == 13) return(3)
    if (var == 14) return(5)
    return(var)
  } else if (wave_age == 19) {
    if (var %in% c(1, 2, 3, 4)) return(0)
    if (var %in% c(5, 6, 7, 8, 9, 10)) return(1)
    if (var %in% c(11, 12, 13)) return(2)
    if (var %in% c(14, 15)) return(3)
    if (var == 16) return(5)
    return(var)
  } else if (wave_age == 20) {
    if (var == -94) return(-8)
    if (var == -91) return(5)
    if (var %in% c(1, 2)) return(2)
    if (var %in% c(3, 5)) return(1)
    if (var %in% c(4, 6, 7, 8, 9)) return(1)
    if (var %in% c(10, 11, 12, 13)) return(0)
    if (var == 14) return(3)
    return(var)
  }
  return(var)
}

# Function to map adult education aims
map_adult_education <- function(education_vars, economic_activity) {
  # Not studying
  if (!is.na(economic_activity) && economic_activity %in% c(6, 7)) {
    return(5)
  }

  # NVQ 4-5 equivalent (0)
  if (any(education_vars$W8VCQUC0K == 1, education_vars$W8ACQUC0A == 1,
          education_vars$W8ACQUC0B == 1, education_vars$W8ACQUC0C == 1,
          education_vars$W9VCQUC0C == 1, education_vars$W9VCQUC0D == 1,
          education_vars$W9ACQUC0A == 1, education_vars$W9ACQUC0B == 1,
          education_vars$W9ACQUC0C == 1)) {
    return(0)
  }

  # NVQ 1-3 equivalent (1)
  if (any(education_vars$W8VCQUC0J == 1, education_vars$W8VCQUC0E == 1,
          education_vars$W8VCQUC0F == 1, education_vars$W8VCQUC0G == 1,
          education_vars$W8VCQUC0H == 1, education_vars$W9VCQUC0E == 1,
          education_vars$W9VCQUC0F == 1, education_vars$W9VCQUC0G == 1,
          education_vars$W9VCQUC0H == 1, education_vars$W9VCQUC0I == 1)) {
    return(1)
  }

  # Entry level (2)
  if (any(education_vars$W8VCQUC0D == 1, education_vars$W8VCQUC0C == 1,
          education_vars$W9VCQUC0K == 1, education_vars$W9VCQUC0L == 1,
          education_vars$W9VCQUC0M == 1)) {
    return(2)
  }

  # Other (3)
  if (any(education_vars$W8VCQUC0A == 1, education_vars$W8VCQUC0B == 1,
          education_vars$W8VCQUC0I == 1, education_vars$W8VCQUC0N == 1,
          education_vars$W9VCQUC0A == 1, education_vars$W9VCQUC0B == 1,
          education_vars$W9VCQUC0R == 1, education_vars$W9VCQUC0S == 1,
          education_vars$W9VCQUC0T == 1)) {
    return(3)
  }

  # None of these (4)
  if (any(education_vars$W8ACQUC0O == 1, education_vars$W8VCQUC0AG == 1,
          education_vars$W9ACQUC0S == 1, education_vars$W9VCQUC0AG == 1)) {
    return(4)
  }

  # Default to -3 for all other cases
  -3
}

# Create education aim variables
merged_data <- merged_data %>%
  mutate(
    educaim17 = map_int(w4saim, ~ map_young_education(.x, 17)),
    educaim19 = map_int(W6Saim, ~ map_young_education(.x, 19)),
    educaim20 = map_int(W7SAim, ~ map_young_education(.x, 20))
  )

# Create educaim25
merged_data <- merged_data %>%
  mutate(
    educaim25 = if_else(
      !is.na(W8ACTIVITY05) & W8ACTIVITY05 %in% c(6, 7), 5,
      if_else(
        any(W8VCQUC0K == 1, W8ACQUC0A == 1, W8ACQUC0B == 1, W8ACQUC0C == 1,
            W9VCQUC0C == 1, W9VCQUC0D == 1, W9ACQUC0A == 1, W9ACQUC0B == 1, W9ACQUC0C == 1), 0,
        if_else(
          any(W8VCQUC0J == 1, W8VCQUC0E == 1, W8VCQUC0F == 1, W8VCQUC0G == 1,
              W8VCQUC0H == 1, W9VCQUC0E == 1, W9VCQUC0F == 1, W9VCQUC0G == 1,
              W9VCQUC0H == 1, W9VCQUC0I == 1), 1,
          if_else(
            any(W8VCQUC0D == 1, W8VCQUC0C == 1, W9VCQUC0K == 1, W9VCQUC0L == 1, W9VCQUC0M == 1), 2,
            if_else(
              any(W8VCQUC0A == 1, W8VCQUC0B == 1, W8VCQUC0I == 1, W8VCQUC0N == 1,
                  W9VCQUC0A == 1, W9VCQUC0B == 1, W9VCQUC0R == 1, W9VCQUC0S == 1, W9VCQUC0T == 1), 3,
              if_else(
                any(W8ACQUC0O == 1, W8VCQUC0AG == 1, W9ACQUC0S == 1, W9VCQUC0AG == 1), 4,
                -3
              )
            )
          )
        )
      )
    )
  )

# Create educaim32
merged_data <- merged_data %>%
  mutate(
    educaim32 = if_else(
      !is.na(W9ECONACT2) & W9ECONACT2 %in% c(6, 7), 5,
      if_else(
        any(W9VCQUC0C == 1, W9VCQUC0D == 1, W9ACQUC0A == 1, W9ACQUC0B == 1, W9ACQUC0C == 1), 0,
        if_else(
          any(W9VCQUC0E == 1, W9VCQUC0F == 1, W9VCQUC0G == 1, W9VCQUC0H == 1, W9VCQUC0I == 1), 1,
          if_else(
            any(W9VCQUC0K == 1, W9VCQUC0L == 1, W9VCQUC0M == 1), 2,
            if_else(
              any(W9VCQUC0A == 1, W9VCQUC0B == 1, W9VCQUC0R == 1, W9VCQUC0S == 1, W9VCQUC0T == 1), 3,
              if_else(
                any(W9ACQUC0S == 1, W9VCQUC0AG == 1), 4,
                -3
              )
            )
          )
        )
      )
    )
  )

# Handle missing values
merged_data <- merged_data %>%
  mutate(
    educaim17 = recode(educaim17, '-999' = -3, '-998' = -2, '-997' = -2, '-995' = -2, '-99' = -3, '-94' = -8, '-92' = -9, '-91' = -1),
    educaim19 = recode(educaim19, '-999' = -3, '-998' = -2, '-997' = -2, '-995' = -2, '-99' = -3, '-94' = -8, '-92' = -9, '-91' = -1),
    educaim20 = recode(educaim20, '-999' = -3, '-998' = -2, '-997' = -2, '-995' = -2, '-99' = -3, '-94' = -8, '-92' = -9, '-91' = -1),
    educaim25 = recode(educaim25, '-9' = -9, '-8' = -8, '-1' = -1),
    educaim32 = recode(educaim32, '-9' = -9, '-8' = -8, '-3' = -3, '-1' = -1)
  )

# Select only required variables
output_data <- merged_data %>%
  select(NSID, educaim17, educaim19, educaim20, educaim25, educaim32)

# Write to CSV
write_csv(output_data, 'data/output/cleaned_data.csv')

